def _new_key(type_name: str, save: bool) -> str:
    if save:
        return web.ctx.site.new_key(f'/type/{type_name}')
    prefix = {'edition': '/books', 'work': '/works', 'author': '/authors'}[type_name]
    return f'{prefix}/__new__{uuid4()}'


def load_author_import_records(authors_in, edits, source, save: bool = True):
    """
    Steps through an import record's authors, and creates new records if new,
    adding them to 'edits' to be saved later.

    :param list authors_in: import author dicts [{"name:" "Bob"}, ...], maybe dates
    :param list edits: list of Things to be saved later. Is modified by this method.
    :param str source: Source record e.g. marc:marc_ex/part01.dat:26456929:680
    :rtype: tuple
    :return: (list, list) authors [{"key": "/author/OL..A"}, ...], author_reply
    """
    authors = []
    author_reply = []
    for author in authors_in:
        if isinstance(author, dict):
            if author.get('type', {}).get('key') == '/type/author':
                a = author.copy()
            elif author.get('name'):
                a = author_import_record_to_author(author)
            elif author.get('key'):
                a = web.ctx.site.get(author['key'])
            else:
                continue
        else:
            a = author
        if not a:
            continue
        new_author = 'key' not in a
        if new_author:
            a['key'] = _new_key('author', save)
            a['source_records'] = [source]
            edits.append(a)
        modified_author = False
        if not new_author and not isinstance(a, dict):
            # Matching an author can add a death date or remote identifier.
            # Record that change without mutating the stored Author object.
            existing = web.ctx.site.get(a.key)
            if existing and a.dict() != existing.dict():
                updated = a.dict()
                for field in ('id', 'revision', 'latest_revision', 'created', 'last_modified'):
                    updated.pop(field, None)
                edits.append(updated)
                modified_author = True
        authors.append({'key': a['key']})
        author_reply.append(
            {
                'key': a['key'],
                'name': a['name'],
                'status': (
                    'created' if new_author else 'modified' if modified_author else 'matched'
                ),
            }
        )
    return (authors, author_reply)


def build_author_reply(authors_in, edits, source, save: bool = True):
    """Compatibility alias for the earlier author reply helper."""
    return load_author_import_records(authors_in, edits, source, save=save)


